_FALLBACK_SRC = '# Action format: [(from_node, to_node, count), ...]\n# "served_i = capacity_i * demand / max(total_capacity, demand)"\n# "capacity_i = drones_i * drone_capacity" (drone_capacity = 5).\n# "upkeep_i = UPKEEP * (DRONES_PER_PLAYER - drones_i at own base)"\n# Moves use only start-of-turn drones, and each drone moves at most one edge.\n#\n# Conservative, deterministic forecast planning. Every proposed trip pays for\n# its travel, forecast upkeep, and a reserved full return-home cost. Revenue\n# beyond the exact forecast is never assumed. No opponent-denial bonus is used.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 100\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for u, v in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if row[v] < 0:\n                    row[v] = row[u] + 1\n                    queue.append(v)\n        distances.append(row)\n\n    hops = [[u for _ in range(n)] for u in range(n)]\n    for u in range(n):\n        for target in range(n):\n            if u != target and distances[u][target] > 0:\n                for v in adjacency[u]:\n                    if distances[v][target] == distances[u][target] - 1:\n                        hops[u][target] = v\n                        break\n    return adjacency, distances, hops\n\n\ndef payout(own_drones, opponent_drones, demand):\n    capacity = DRONE_CAPACITY * own_drones\n    total_capacity = DRONE_CAPACITY * (own_drones + opponent_drones)\n    denominator = max(total_capacity, demand)\n    if denominator <= 0:\n        return 0.0\n    return capacity * demand / denominator\n\n\ndef trajectory(source, target, horizon, hops):\n    path = []\n    position = source\n    for _ in range(horizon):\n        if position != target:\n            position = hops[position][target]\n        path.append(position)\n    return path\n\n\ndef conservative_plan(obs, distances, hops):\n    n = int(obs["n_nodes"])\n    home = int(obs["player_base"])\n    enemy_home = int(obs["opponent_base"])\n    own = obs["player_drones"]\n    enemy = obs["opponent_drones"]\n    forecast = obs["demand_forecast"]\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    horizon = min(5, remaining, min((len(x) for x in forecast), default=0))\n    if horizon <= 0:\n        return []\n\n    # First reserve everyone\'s safe retreat. Improving one drone\'s route at a\n    # time then accounts for every other drone already allocated to each node.\n    sources = []\n    for node in range(n):\n        sources.extend([node] * max(0, int(own[node])))\n    sources.sort(key=lambda s: (s == home, distances[s][home], s))\n    routes = [trajectory(s, home, horizon, hops) for s in sources]\n    counts = [[0] * n for _ in range(horizon)]\n    for route in routes:\n        for k, node in enumerate(route):\n            counts[k][node] += 1\n\n    def route_value(route):\n        value = 0.0\n        for k, node in enumerate(route):\n            if node == home:\n                continue\n            demand = float(forecast[node][k])\n            other = counts[k][node]\n            # Opponent positions are visible, but their future actions are not.\n            # Avoid fights rather than assigning speculative denial value.\n            opposition = int(enemy[node])\n            value += (\n                payout(other + 1, opposition, demand)\n                - payout(other, opposition, demand)\n                - UPKEEP\n            )\n        # Reserve every remaining step of a return trip, without assuming any\n        # revenue on that trip. Near game end reserve only costs still payable.\n        return_steps = min(\n            max(0, remaining - horizon),\n            max(0, distances[route[-1]][home]),\n        )\n        return value - UPKEEP * return_steps\n\n    for index, source in enumerate(sources):\n        old_route = routes[index]\n        for k, node in enumerate(old_route):\n            counts[k][node] -= 1\n\n        best_route = old_route\n        best_value = route_value(old_route)\n        candidates = sorted(range(n), key=lambda v: (distances[source][v], v))\n        for target in candidates:\n            if target == home or target == enemy_home:\n                continue\n            if int(enemy[target]) > 0:\n                continue\n            distance = distances[source][target]\n            if distance < 0 or distance > horizon:\n                continue\n            candidate = trajectory(source, target, horizon, hops)\n            value = route_value(candidate)\n            # A meaningful buffer prevents chasing tiny forecast advantages.\n            # From home the retreat alternative has exactly zero value.\n            if value > best_value + 0.75:\n                best_value = value\n                best_route = candidate\n\n        routes[index] = best_route\n        for k, node in enumerate(best_route):\n            counts[k][node] += 1\n\n    return [(source, route[0]) for source, route in zip(sources, routes)]\n\n\ndef legal_action(plan, own, adjacency):\n    available = [max(0, int(x)) for x in own]\n    n = len(available)\n    grouped = {}\n    for source, target in plan:\n        source, target = int(source), int(target)\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if source == target or target not in adjacency[source]:\n            continue\n        if available[source] <= 0:\n            continue\n        available[source] -= 1\n        pair = (source, target)\n        grouped[pair] = grouped.get(pair, 0) + 1\n\n    # Replay the aggregated action against start-of-turn availability.\n    available = [max(0, int(x)) for x in own]\n    result = []\n    for (source, target), requested in sorted(grouped.items()):\n        count = min(int(requested), available[source])\n        if count > 0 and target in adjacency[source]:\n            result.append((int(source), int(target), int(count)))\n            available[source] -= count\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        # No match-history dependence: only static map data is cached.\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        edges = obs.get("edges", [])\n        key = (n, tuple((int(u), int(v)) for u, v in edges))\n        if key != self.map_key:\n            self.map_data = preprocess_map(n, edges)\n            self.map_key = key\n        adjacency, distances, hops = self.map_data\n        own = obs.get("player_drones", [])\n        if len(own) != n or not obs.get("demand_forecast"):\n            return []\n        plan = conservative_plan(obs, distances, hops)\n        return legal_action(plan, own, adjacency)\n'
